import React,{useState} from 'react';import {useAuth} from '../contexts/AuthContext';import {useNavigate,Link} from 'react-router-dom';
export default function Login(){const [email,setEmail]=useState('');const [password,setPassword]=useState('');const {signIn}=useAuth();const navigate=useNavigate();const handleSubmit=async e=>{e.preventDefault();const {error}=await signIn(email,password);if(!error)navigate('/app');};return(<div className="min-h-screen flex items-center justify-center bg-gray-100"><form onSubmit={handleSubmit} className="bg-white p-8 rounded-xl shadow-md w-96"><h1 className="text-2xl font-bold mb-6">Sign In</h1><input type="email" placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} className="w-full p-3 border rounded mb-4" required/><input type="password" placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)} className="w-full p-3 border rounded mb-4" required/><button className="w-full bg-green-600 text-white p-3 rounded font-bold">Sign In</button><div className="mt-4 text-center text-sm"><Link to="/forgot-password" className="text-green-600">Forgot password?</Link></div><div className="mt-4 text-center text-sm"><span className="text-gray-500">Don't have an account?</span> <Link to="/subscribe" className="text-green-600 font-medium">Subscribe</Link></div></form></div>);}
